    private VBoxContainer ContentPanel(Control owner,string caption,out HBoxContainer header,bool clip=false)
    {
        var panel=new PanelContainer{ClipContents=clip,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};panel.AddThemeStyleboxOverride("panel",box(new Color("121d28"),new Color("385064"),7,5));owner.Get("inspector").As<Node>().AddChild(panel);var column=new VBoxContainer();column.AddThemeConstantOverride("separation",4);panel.AddChild(column);header=new HBoxContainer();column.AddChild(header);var title=new Label{Text=caption,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,ClipText=clip};title.AddThemeColorOverride("font_color",new Color("8fa8bb"));header.AddChild(title);return column;
    }
    public void text_settings_property(Control owner,Resource layer)
    {
        var properties=layer.Get("properties").AsGodotDictionary();var settings=ResourceValue(Get(properties,"text_settings"));if(!properties.ContainsKey("text_settings"))settings=ensure_text_settings(layer);var column=ContentPanel(owner,"TEXT SETTINGS",out var row);row.AddChild(new Label{Text=settings!=null?Get(properties,"text_settings_path","Embedded").AsString().GetFile():"Empty",TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,CustomMinimumSize=new Vector2(70,0)});var menu=new MenuButton{Text="⋮"};row.AddChild(menu);foreach(string name in new[]{"New","Load from project…","Save As…","Clear"})menu.GetPopup().AddItem(name);menu.GetPopup().IdPressed+=index=>{switch(index){case 0:Action(owner,()=>{properties["text_settings"]=default_text_settings();properties.Remove("text_settings_path");});break;case 1:owner.Call("_choose_text_settings",layer);break;case 2:owner.Call("_save_text_settings",layer);break;case 3:Action(owner,()=>{properties["text_settings"]=default(Variant);properties.Remove("text_settings_path");});break;}};if(settings==null)return;var values=settings.Get("values").AsGodotDictionary();button(owner,column,Get(values,"font","Arial").AsString(),new Callable(owner,"_font_menu"),"Choose a system font","");
        void Num(string title,string key,double fallback,double min,double max,double step,bool integer=false)=>number(owner,column,title,Get(values,key,fallback).AsDouble(),Callable.From<double>(value=>set_text_setting(layer,key,integer?Variant.From((int)value):Variant.From(value))),min,max,step);
        void Check(string title,string key,bool fallback)=>check(owner,column,title,Get(values,key,fallback).AsBool(),Callable.From<bool>(value=>set_text_setting(layer,key,value)));
        void ColorField(string title,string key,Color fallback)=>color(owner,column,title,Get(values,key,fallback).AsColor(),Callable.From<Color>(value=>set_text_setting(layer,key,value)));
        Num("Font size","font_size",72,1,1000,1);Check("Bold","bold",false);Check("Italic","italic",false);Num("Letter spacing","letter_spacing",0,-64,256,1,true);Num("Line spacing","line_spacing",0,-64,256,1,true);ColorField("Color","color",Colors.White);Num("Outline","outline_size",0,0,64,1,true);ColorField("Outline color","outline_color",Colors.Black);Check("Shadow","shadow",false);if(Get(values,"shadow",false).AsBool()){ColorField("Shadow color","shadow_color",new Color(0,0,0,.65f));var offset=Get(values,"shadow_offset",new Vector2(2,2)).AsVector2();for(int i=0;i<2;i++){int axis=i;number(owner,column,axis==0?"Shadow X":"Shadow Y",offset[axis],Callable.From<double>(value=>set_text_setting_component(layer,"shadow_offset",axis,value)),-100000,100000,.1);}}
    }
    public void noise_layer_property(Control owner,Resource layer)
    {
        var properties=layer.Get("properties").AsGodotDictionary();var resource=ResourceValue(Get(properties,"noise_object"));if(resource==null){resource=default_noise_image();properties["noise_object"]=resource;refresh_noise_layer(layer);}var values=resource.Get("values").AsGodotDictionary();var column=ContentPanel(owner,"NOISE IMAGE",out var row);row.AddChild(new TextureRect{Texture=layer.Get("texture").As<Texture2D>(),CustomMinimumSize=new Vector2(46,30),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered});var menu=new MenuButton{Text="Change…"};row.AddChild(menu);menu.GetPopup().AddItem("New Noise Image",0);menu.GetPopup().AddItem("Load from project…",1);menu.GetPopup().IdPressed+=id=>{if(id==0)Action(owner,()=>{properties["noise_object"]=default_noise_image();refresh_noise_layer(layer);});else owner.Call("_load_noise_layer_object",layer);};var type=new OptionButton();foreach(string name in new[]{"Simplex","Simplex Smooth","Cellular","Perlin","Value Cubic","Value"})type.AddItem(name);type.Select(Math.Clamp(Get(values,"noise_type",1).AsInt32(),0,5));column.AddChild(type);type.ItemSelected+=value=>Action(owner,()=>set_noise_object_value(layer,"noise_type",value));
        void Num(string title,string key,double fallback,double min,double max)=>number(owner,column,title,Get(values,key,fallback).AsDouble(),Callable.From<double>(value=>set_noise_object_value(layer,key,(int)value)),min,max,1);
        void Slider(string title,string key,double fallback,double min,double max)=>slider(owner,column,title,Get(values,key,fallback).AsDouble(),min,max,Callable.From<double>(value=>set_noise_object_value(layer,key,value)));
        void ColorField(string title,string key,Color fallback)=>color(owner,column,title,Get(values,key,fallback).AsColor(),Callable.From<Color>(value=>set_noise_object_value(layer,key,value)));
        void Check(string title,string key,bool fallback)=>check(owner,column,title,Get(values,key,fallback).AsBool(),Callable.From<bool>(value=>set_noise_object_value(layer,key,value)));
        Num("Seed","seed",0,int.MinValue,int.MaxValue);Slider("Frequency","frequency",.015,.0001,.25);Num("Octaves","octaves",5,1,10);Slider("Lacunarity","lacunarity",2,.01,8);Slider("Gain","gain",.5,0,2);Slider("Contrast","contrast",1,.01,4);ColorField("Low color","low_color",Colors.Black);ColorField("High color","high_color",Colors.White);Check("Seamless","seamless",true);Check("Invert","invert",false);Check("Show as normal map","as_normal_map",false);
