    public void image_source_property(Control owner,Resource layer)
    {
        var properties=layer.Get("properties").AsGodotDictionary();var column=ContentPanel(owner,"IMAGE",out var row,true);row.AddChild(new TextureRect{Texture=layer.Get("texture").As<Texture2D>(),CustomMinimumSize=new Vector2(46,34),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered});var menu=new MenuButton{Text="Change…"};column.AddChild(menu);foreach(string title in new[]{"Load from project…","Create Noise Image","Clear"})menu.GetPopup().AddItem(title);menu.GetPopup().IdPressed+=index=>{if(index==0)owner.Call("_replace_image");else if(index==1)create_noise_image(owner,layer);else Action(owner,()=>{layer.Set("texture",default(Variant));properties.Remove("noise_image");});};var data=Get(properties,"noise_image");if(data.VariantType!=Variant.Type.Dictionary)return;var config=data.AsGodotDictionary();var badge=new Label{Text="PROCEDURAL NOISE"};badge.AddThemeColorOverride("font_color",new Color("70cdb8"));column.AddChild(badge);var resolution=new OptionButton();foreach(int size in new[]{64,128,256,512})resolution.AddItem(size+" × "+size);resolution.Select(Get(config,"resolution",2).AsInt32());column.AddChild(resolution);resolution.ItemSelected+=value=>Action(owner,()=>set_noise_value(layer,"resolution",value));var type=new OptionButton();foreach(string name in new[]{"Simplex","Smooth Simplex","Cellular","Perlin","Value Cubic","Value"})type.AddItem(name);type.Select(Get(config,"noise_type",1).AsInt32());column.AddChild(type);type.ItemSelected+=value=>Action(owner,()=>set_noise_value(layer,"noise_type",value));
        void Num(string title,string key,double fallback,double min,double max,bool integer=false)=>number(owner,column,title,Get(config,key,fallback).AsDouble(),Callable.From<double>(value=>set_noise_value(layer,key,integer?Variant.From((int)value):Variant.From(value))),min,max,.1);
        void Slider(string title,string key,double fallback,double min,double max)=>slider(owner,column,title,Get(config,key,fallback).AsDouble(),min,max,Callable.From<double>(value=>set_noise_value(layer,key,value)));
        void ColorField(string title,string key,Color fallback)=>color(owner,column,title,Get(config,key,fallback).AsColor(),Callable.From<Color>(value=>set_noise_value(layer,key,value)));
        void Check(string title,string key,bool fallback)=>check(owner,column,title,Get(config,key,fallback).AsBool(),Callable.From<bool>(value=>set_noise_value(layer,key,value)));
        Num("Seed","seed",0,0,100000,true);Slider("Frequency","frequency",.015,.0001,.2);Num("Octaves","octaves",5,1,10,true);Num("Lacunarity","lacunarity",2,.01,8);Num("Gain","gain",.5,0,2);Slider("Contrast","contrast",1,.01,4);ColorField("Low color","low_color",Colors.Black);ColorField("High color","high_color",Colors.White);Check("Seamless","seamless",true);Check("Invert","invert",false);Check("Normal map","as_normal_map",false);
